from pathlib import Path

ROOT = Path.cwd()
if not (ROOT / 'package.json').exists():
    raise SystemExit('ERROR: Run this patch from the root of sepulchria-portal.')

def write_file(rel, content):
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')
    print(f'OK: wrote {rel}')

def replace_once(rel, old, new, label):
    path = ROOT / rel
    if not path.exists():
        raise SystemExit(f'ERROR: Missing {rel}')
    text = path.read_text(encoding='utf-8')
    if new in text:
        print(f'SKIP: {label} already installed')
        return
    if old not in text:
        raise SystemExit(f'ERROR: Expected code not found for {label} in {rel}. Send me this exact error.')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')
    print(f'OK: {label}')

write_file('lib/private-locations/access.ts', 'import "server-only";\n\nimport {\n  createClient as createAdminClient,\n} from "@supabase/supabase-js";\n\nimport {\n  getStaffSession,\n} from "@/lib/auth/require-staff";\n\ntype PrivateLocationMetadata = {\n  ownerCharacterId: string;\n  backgroundColour: string;\n  textColour: string;\n};\n\nexport type PrivateLocationAccess = {\n  isPrivate: boolean;\n  allowed: boolean;\n  metadata:\n    | PrivateLocationMetadata\n    | null;\n};\n\nfunction createPrivilegedClient() {\n  const url =\n    process.env.NEXT_PUBLIC_SUPABASE_URL;\n\n  const secret =\n    process.env.SUPABASE_SECRET_KEY;\n\n  if (!url || !secret) {\n    throw new Error(\n      "Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SECRET_KEY.",\n    );\n  }\n\n  return createAdminClient(\n    url,\n    secret,\n    {\n      auth: {\n        persistSession: false,\n        autoRefreshToken: false,\n      },\n    },\n  );\n}\n\nexport async function getPrivateLocationAccess(\n  roomId: string,\n  characterId: string,\n): Promise<PrivateLocationAccess> {\n  const admin =\n    createPrivilegedClient();\n\n  const {\n    data: privateRoom,\n    error: privateRoomError,\n  } = await admin\n    .from(\n      "private_location_rooms",\n    )\n    .select(\n      "owner_character_id, background_colour, text_colour",\n    )\n    .eq(\n      "room_id",\n      roomId,\n    )\n    .maybeSingle();\n\n  if (privateRoomError) {\n    throw new Error(\n      `Unable to inspect Private Location: ${privateRoomError.message}`,\n    );\n  }\n\n  if (!privateRoom) {\n    return {\n      isPrivate: false,\n      allowed: true,\n      metadata: null,\n    };\n  }\n\n  const metadata:\n    PrivateLocationMetadata = {\n      ownerCharacterId:\n        privateRoom.owner_character_id,\n      backgroundColour:\n        privateRoom.background_colour,\n      textColour:\n        privateRoom.text_colour,\n    };\n\n  const staff =\n    await getStaffSession();\n\n  if (staff) {\n    return {\n      isPrivate: true,\n      allowed: true,\n      metadata,\n    };\n  }\n\n  const {\n    data: entitlement,\n    error: entitlementError,\n  } = await admin\n    .from(\n      "character_feature_entitlements",\n    )\n    .select("enabled")\n    .eq(\n      "character_id",\n      privateRoom.owner_character_id,\n    )\n    .eq(\n      "feature_key",\n      "private_chat",\n    )\n    .maybeSingle();\n\n  if (entitlementError) {\n    throw new Error(\n      `Unable to verify Private Location entitlement: ${entitlementError.message}`,\n    );\n  }\n\n  if (\n    entitlement?.enabled !== true\n  ) {\n    return {\n      isPrivate: true,\n      allowed: false,\n      metadata,\n    };\n  }\n\n  if (\n    privateRoom.owner_character_id ===\n    characterId\n  ) {\n    return {\n      isPrivate: true,\n      allowed: true,\n      metadata,\n    };\n  }\n\n  const {\n    data: membership,\n    error: membershipError,\n  } = await admin\n    .from(\n      "private_location_members",\n    )\n    .select("status")\n    .eq(\n      "room_id",\n      roomId,\n    )\n    .eq(\n      "character_id",\n      characterId,\n    )\n    .maybeSingle();\n\n  if (membershipError) {\n    throw new Error(\n      `Unable to verify Private Location membership: ${membershipError.message}`,\n    );\n  }\n\n  return {\n    isPrivate: true,\n    allowed:\n      membership?.status ===\n      "active",\n    metadata,\n  };\n}\n')

